	ctx        context.Context
	h          *HugoSites
	sp         *source.SourceSpec
	logger     loggers.Logger
	infoLogger logg.LevelLogger

	m *pageMap

	fs afero.Fs

	// List of paths that have changed. Used in partial builds.
	ids      []pathChange
	seenDirs map[string]bool

